    // FR-525/FR-530: switching to a new conversation clears the retained graph
    // (including a still-present stale session from the previous conversation).
    #[test]
    fn app_dashboard_clears_last_graph_on_new_conversation() {
        let (mut app, _sent) = test_app();
        let hub = dmuxai::web::DashboardHub::new(
            dmuxai::web::SnapshotSource::Tui,
            "/test-workspace".to_owned(),
        );
        app.attach_dashboard(hub.clone());

        let stale_run = GraphRun {
            plan: dmuxai::graph::GraphPlan {
                schema: "dmuxai.graph/v1".to_owned(),
                id: "run-old".to_owned(),
                orchestrator_model: "composer-2.5".to_owned(),
                user_prompt: "old conversation".to_owned(),
                limits: dmuxai::graph::GraphLimits::default(),
                tasks: Vec::new(),
                nodes: vec![],
                edges: vec![],
            },
            conversation_id: app.conversation_id.as_str().to_owned(),
            phase: GraphRunPhase::Completed,
            waiting_gate_node: None,
            ..Default::default()
        };
        app.graph_session = Some(GraphRunSession::new(stale_run.clone()));
        app.last_graph_run = Some(stale_run);
        app.publish_dashboard();
        assert!(hub.snapshot().graph.is_some());

        app.create_conversation(None);

        assert!(app.last_graph_run.is_none());
        assert!(
            hub.snapshot().graph.is_none(),
            "the previous conversation's graph must not leak into a new one"
        );
    }

    fn history_run(
        id: &str,
        conversation_id: &str,
        turn_index: u32,
        prompt: &str,
        phase: GraphRunPhase,
    ) -> GraphRun {
        let status = match phase {
            GraphRunPhase::Completed => dmuxai::graph::GraphNodeStatus::Completed,
            GraphRunPhase::Active => dmuxai::graph::GraphNodeStatus::Running,
            _ => dmuxai::graph::GraphNodeStatus::Pending,
        };
        GraphRun {
            plan: dmuxai::graph::GraphPlan {
                schema: "dmuxai.graph/v1".to_owned(),
                id: id.to_owned(),
                orchestrator_model: "composer-2.5".to_owned(),
                user_prompt: prompt.to_owned(),
                limits: dmuxai::graph::GraphLimits::default(),
                tasks: Vec::new(),
                nodes: vec![dmuxai::graph::GraphNode {
                    id: "step-1".to_owned(),
                    role: dmuxai::graph::NodeRole::Implement,
                    job: prompt.to_owned(),
                    runner: "codex".to_owned(),
                    model_id: "composer-2.5".to_owned(),
                    skill: None,
                    requires_gate: false,
                    status,
                    attempt: 1,
                    task: None,
                    started_at_ms: Some(1_000),
                    finished_at_ms: (phase == GraphRunPhase::Completed).then_some(61_000),
                }],
                edges: Vec::new(),
            },
            conversation_id: conversation_id.to_owned(),
            phase,
            waiting_gate_node: None,
            turn_index,
            ..Default::default()
        }
    }

    fn history_app() -> (PlanGateHarness, dmuxai::web::DashboardHub) {
        let h = plan_gate_test_app();
        let hub = dmuxai::web::DashboardHub::new(
            dmuxai::web::SnapshotSource::Tui,
            h.app.workspace_root.to_string_lossy().into_owned(),
        );
        let mut h = h;
        h.app.attach_dashboard(hub.clone());
        (h, hub)
    }

    // TC-1214 / SPEC-dashboard-fullwidth FR-1222: A -> B -> A restores each
    // conversation's own latest run; B never shows A's.
    #[test]
    fn conversation_switch_restores_own_graph_run() {
        let (mut h, hub) = history_app();
        let a = h.app.conversation_id.clone();
        h.app.input = "/direct first".to_owned();
        h.app.submit_prompt();
        h.app.graph_session = None;
        let ws = h.app.workspace_root.clone();
        for run in [
            history_run("run-a1", a.as_str(), 1, "first", GraphRunPhase::Completed),
            history_run("run-a2", a.as_str(), 2, "second", GraphRunPhase::Completed),
        ] {
            dmuxai::graph::save_run(&ws, &run).expect("save a");
        }

        h.app.create_conversation(Some("B".to_owned()));
        let b = h.app.conversation_id.clone();
        assert_ne!(a, b);
        assert!(h.app.last_graph_run.is_none(), "B has no runs yet");
        assert!(hub.snapshot().graph.is_none(), "B must not show A's run");
        dmuxai::graph::save_run(
            &ws,
            &history_run("run-b1", b.as_str(), 1, "bee", GraphRunPhase::Completed),
        )
        .expect("save b");

        h.app.select_conversation(a.clone());
        let graph = hub.snapshot().graph.expect("A's graph restored");
        assert_eq!(graph.id, "run-a2");
        let bands: Vec<&str> = graph.turns.iter().map(|t| t.run_id.as_str()).collect();
        assert!(
            bands.contains(&"run-a1") && bands.contains(&"run-a2"),
            "{bands:?}"
        );
        assert!(!bands.contains(&"run-b1"), "{bands:?}");
        assert_eq!(graph.turns[0].steps.len(), 1);

        h.app.select_conversation(b.clone());
        let graph = hub.snapshot().graph.expect("B's graph restored");
        assert_eq!(graph.id, "run-b1");
        assert!(graph.turns.iter().all(|t| t.run_id == "run-b1"));

        h.app.select_conversation(a);
        assert_eq!(hub.snapshot().graph.unwrap().id, "run-a2");
    }

    // TC-1215 / FR-1222: a run left mid-run is shown cancelled (file kept);
    // a live run of the conversation wins; a stored awaiting run is stale.
    #[test]
    fn restored_graph_history_is_safe() {
        let (mut h, hub) = history_app();
        let a = h.app.conversation_id.clone();
        h.app.input = "/direct first".to_owned();
        h.app.submit_prompt();
        h.app.graph_session = None;
        let ws = h.app.workspace_root.clone();
        let mid = history_run("run-mid", a.as_str(), 5, "mid", GraphRunPhase::Active);
        dmuxai::graph::save_run(&ws, &mid).expect("save mid");
        h.app.create_conversation(None);
        h.app.select_conversation(a.clone());
        let run = h.app.last_graph_run.as_ref().expect("history");
        assert_eq!(run.plan.id, "run-mid");
        assert_eq!(run.phase, GraphRunPhase::Cancelled);
        assert!(h.app.graph_session.is_none(), "history never resumes");
        assert_eq!(
            dmuxai::graph::load_run(&ws, "run-mid").unwrap().phase,
            GraphRunPhase::Active,
            "the stored record is not rewritten"
        );
        assert_eq!(
            hub.snapshot().graph.unwrap().phase,
            GraphRunPhase::Cancelled
        );

        // A live run of the active conversation takes precedence.
        let live = history_run("run-live", a.as_str(), 6, "live", GraphRunPhase::Active);
        h.app.create_conversation(None);
        h.app.graph_session = Some(GraphRunSession::new(live));
        h.app.select_conversation(a.clone());
        h.app.publish_dashboard();
        let graph = hub.snapshot().graph.unwrap();
        assert_eq!(graph.id, "run-live");
        assert_eq!(graph.phase, GraphRunPhase::Active);
        h.app.graph_session = None;
    }

    // TC-1216 / FR-1224: the dashboard can show an older run of this
    // conversation, never another conversation's, and not over a pending plan.
    #[test]
    fn show_graph_run_command_is_scoped() {
        let (mut h, hub) = history_app();
        let a = h.app.conversation_id.clone();
        h.app.input = "/direct first".to_owned();
        h.app.submit_prompt();
        h.app.graph_session = None;
        let ws = h.app.workspace_root.clone();
        dmuxai::graph::save_run(
            &ws,
            &history_run("run-a1", a.as_str(), 1, "first", GraphRunPhase::Completed),
        )
        .unwrap();
        dmuxai::graph::save_run(
            &ws,
            &history_run("run-a2", a.as_str(), 2, "second", GraphRunPhase::Completed),
        )
        .unwrap();
        dmuxai::graph::save_run(
            &ws,
            &history_run(
                "run-other",
                "other-conversation",
                1,
                "x",
                GraphRunPhase::Completed,
            ),
        )
        .unwrap();
        h.app.create_conversation(None);
        h.app.select_conversation(a.clone());
        assert_eq!(h.app.last_graph_run.as_ref().unwrap().plan.id, "run-a2");

        let parsed: SessionCommand =
            serde_json::from_str(r#"{"command":"show_graph_run","run_id":"run-a1"}"#)
                .expect("dashboard JSON parses");
        h.app
            .handle_session_command(parsed)
            .expect("show older run");
        h.app.publish_dashboard();
        assert_eq!(hub.snapshot().graph.unwrap().id, "run-a1");

        let other = h.app.handle_session_command(SessionCommand::ShowGraphRun {
            run_id: "run-other".to_owned(),
        });
        assert!(matches!(other, Err(RunTodoError::Missing(_))), "{other:?}");
        let bad = h.app.handle_session_command(SessionCommand::ShowGraphRun {
            run_id: "../run-a1".to_owned(),
        });
        assert!(matches!(bad, Err(RunTodoError::Invalid(_))), "{bad:?}");
        assert_eq!(h.app.last_graph_run.as_ref().unwrap().plan.id, "run-a1");

        // A plan waiting for approval is never replaced.
        let mut pending = history_run(
            "run-wait",
            a.as_str(),
            3,
            "wait",
            GraphRunPhase::AwaitingApproval,
        );
        pending.plan.nodes.clear();
        h.app.last_graph_run = Some(pending);
        let busy = h.app.handle_session_command(SessionCommand::ShowGraphRun {
            run_id: "run-a2".to_owned(),
        });
        assert!(matches!(busy, Err(RunTodoError::Busy(_))), "{busy:?}");
        assert_eq!(h.app.last_graph_run.as_ref().unwrap().plan.id, "run-wait");
    }

    fn other_workspace_conversation(
        repos: &std::path::Path,
        title: &str,
    ) -> (tempfile::TempDir, String, String) {
        let other = tempfile::tempdir().unwrap();
        let key = dmuxai::workspace::normalize_workspace_path(other.path()).unwrap();
        let db = repos
            .join(dmuxai::state_path::repo_key_for_canonical(&key))
            .join("conversations.sqlite3");
        let mut engine = ConversationEngine::open(&db, other.path()).unwrap();
        let snapshot = engine
            .select(ConversationSelection::New {
                title: Some(title.to_owned()),
            })
            .unwrap();
        let id = snapshot.id.as_str().to_owned();
        drop(engine);
        (other, key, id)
    }

    // TC-1221 / SPEC-dashboard-fullwidth FR-1225: the session view groups
    // other workspaces' sessions (read from the state dir) after the current
    // workspace's group.
    #[test]
    fn session_view_groups_other_workspaces() {
        let (mut h, _hub) = history_app();
        let state = tempfile::tempdir().unwrap();
        let repos = state.path().join("repos");
        let (_other, key, id) = other_workspace_conversation(&repos, "Other chat");
        assert!(h.app.session_view().workspaces.len() <= 1);
        h.app.set_state_repos_dir(Some(repos));
        let view = h.app.session_view();
        assert_eq!(view.workspaces.len(), 2, "{:?}", view.workspaces);
        let current = &view.workspaces[0];
        assert!(current.current && current.available);
        assert_eq!(current.path, h.app.engine.workspace_key());
        assert!(current.conversations.is_empty());
        let other = &view.workspaces[1];
        assert!(!other.current && other.available);
        assert_eq!(other.path, key);
        assert_eq!(
            other.name,
            std::path::Path::new(&key)
                .file_name()
                .unwrap()
                .to_string_lossy()
        );
        assert_eq!(other.conversations.len(), 1);
        assert_eq!(other.conversations[0].id, id);
        assert_eq!(other.conversations[0].title, "Other chat");
        assert!(view.conversations.iter().all(|c| c.id != id));
    }

    // TC-1222 / FR-1225: group labels and ordering.
    #[test]
    fn workspace_group_labels_and_order() {
        let meta = workspace_group_meta("/home/u/src/dmux", Some("/home/u"), None);
        assert_eq!((meta.name.as_str(), meta.label.as_str()), ("dmux", "~/src"));
        let meta = workspace_group_meta("/home/u/dmux", Some("/home/u/"), None);
        assert_eq!(meta.label, "~");
        let meta = workspace_group_meta("/srv/app", Some("/home/u"), None);
        assert_eq!((meta.name.as_str(), meta.label.as_str()), ("app", "/srv"));
        let meta = workspace_group_meta("/home/u/src/dmux", Some("/home/u"), Some("Ubuntu"));
        assert_eq!(meta.label, "WSL: Ubuntu");
        let conv = |id: &str, at: u64| SessionConversation {
            id: id.to_owned(),
            title: id.to_owned(),
            updated_at_ms: at,
            ..Default::default()
        };
        let groups = group_other_workspaces(
            vec![
                ("/w/b".to_owned(), conv("b2", 90)),
                ("/w/a".to_owned(), conv("a1", 50)),
                ("/w/b".to_owned(), conv("b1", 10)),
                ("/w/gone".to_owned(), conv("g1", 5)),
            ],
            None,
            None,
            |path| path != "/w/gone",
        );
        let paths: Vec<&str> = groups.iter().map(|g| g.path.as_str()).collect();
        assert_eq!(paths, ["/w/b", "/w/a", "/w/gone"]);
        assert_eq!(groups[0].updated_at_ms, 90);
        let ids: Vec<&str> = groups[0]
            .conversations
            .iter()
            .map(|c| c.id.as_str())
            .collect();
        assert_eq!(ids, ["b2", "b1"]);
        assert!(groups[0].available && !groups[2].available);
    }

    // TC-1223 / FR-1227: opening another workspace's session is prepared,
    // validated and handed to the re-exec only for that workspace.
    #[test]
    fn prepare_open_conversation_is_scoped() {
        let (mut h, _hub) = history_app();
        let state = tempfile::tempdir().unwrap();
        let repos = state.path().join("repos");
        let (other, key, id) = other_workspace_conversation(&repos, "Other chat");
        h.app.set_state_repos_dir(Some(repos));
        let parsed: SessionCommand = serde_json::from_value(serde_json::json!({
            "command": "prepare_open_conversation",
            "workspace": key,
            "id": id,
        }))
        .unwrap();
        h.app.handle_session_command(parsed).unwrap();
        let unrelated = tempfile::tempdir().unwrap();
        assert_eq!(h.app.take_switch_open_conversation(unrelated.path()), None);
        h.app
            .handle_session_command(SessionCommand::PrepareOpenConversation {
                workspace: key.clone(),
                id: id.clone(),
            })
            .unwrap();
        assert_eq!(
            h.app.take_switch_open_conversation(other.path()),
            Some(id.clone())
        );
        assert_eq!(h.app.take_switch_open_conversation(other.path()), None);
        // A cancelled switch forgets it.
        h.app.prepare_open_conversation(&key, &id).unwrap();
        h.app.cancel_workspace_switch("cancelled".to_owned());
        assert_eq!(h.app.take_switch_open_conversation(other.path()), None);
        // Unknown ids, ids of the current workspace and bad ids are refused.
        let missing = h.app.prepare_open_conversation(&key, "nope");
        assert!(
            matches!(missing, Err(RunTodoError::Missing(_))),
            "{missing:?}"
        );
        let current = h.app.engine.workspace_key().to_owned();
        let own = h.app.conversation_id.as_str().to_owned();
        let same = h.app.prepare_open_conversation(&current, &own);
        assert!(matches!(same, Err(RunTodoError::Invalid(_))), "{same:?}");
        let bad = h.app.prepare_open_conversation(&key, "../x");
        assert!(matches!(bad, Err(RunTodoError::Invalid(_))), "{bad:?}");
        // While a switch is pending nothing new is prepared.
        h.app.switch_pending = Some(other.path().to_path_buf());
        let busy = h.app.prepare_open_conversation(&key, &id);
        assert!(matches!(busy, Err(RunTodoError::Busy(_))), "{busy:?}");
    }

    // TC-1223 / FR-1227: the re-exec'd process opens the requested
    // conversation of its own workspace and ignores anything else.
    #[test]
    fn open_conversation_on_startup_selects_it() {
        let (mut h, _hub) = history_app();
        let first = h.app.conversation_id.clone();
        h.app.create_conversation(Some("second".to_owned()));
        let second = h.app.conversation_id.clone();
        assert_ne!(first, second);
        h.app.open_conversation_on_startup("not-a-conversation");
        assert_eq!(h.app.conversation_id, second);
        h.app.open_conversation_on_startup(first.as_str());
        assert_eq!(h.app.conversation_id, first);
    }

    // TC-1217 / FR-1223: bands link to their own user message, in order, even
    // when a prompt repeats or carries a route prefix.
    #[test]
    fn turn_bands_link_to_user_messages() {
        let runs = vec![
            history_run("r1", "c", 1, "fix it", GraphRunPhase::Completed),
            history_run("r2", "c", 2, "add docs", GraphRunPhase::Completed),
            history_run("r3", "c", 3, "fix it", GraphRunPhase::Completed),
            history_run("r4", "c", 4, "never sent", GraphRunPhase::Completed),
        ];
        let mut bands: Vec<dmuxai::web::TurnBandView> = runs
            .iter()
            .map(|run| dmuxai::web::TurnBandView {
                run_id: run.plan.id.clone(),
                turn_index: run.turn_index,
                phase: run.phase,
                user_prompt: run.plan.user_prompt.clone(),
                nodes: vec!["step-1".to_owned()],
                message_id: Some("stale".to_owned()),
                steps: Vec::new(),
            })
            .collect();
        let users = [(1, "fix it"), (4, "/plan add docs"), (7, "fix it")];
        link_turn_bands_to_messages(&mut bands, &runs, &users, "c");
        let ids: Vec<Option<&str>> = bands.iter().map(|b| b.message_id.as_deref()).collect();
        assert_eq!(ids, vec![Some("c:1"), Some("c:4"), Some("c:7"), None]);
    }

    // TC-703 / FR-702: running graph nodes carry log_tail (last 20 lines, truncated to 300 chars)
    // and changed_files (workspace-relative, max 50, no paths outside workspace).
    #[test]
    fn dashboard_nodes_carry_log_tail_and_changed_files() {
        let (mut app, _sent) = test_app();
        let hub = dmuxai::web::DashboardHub::new(
            dmuxai::web::SnapshotSource::Tui,
            app.workspace_root.to_string_lossy().into_owned(),
        );
        app.attach_dashboard(hub.clone());

        app.graph_session = Some(GraphRunSession::new(GraphRun {
            plan: dmuxai::graph::GraphPlan {
                schema: "dmuxai.graph/v1".to_owned(),
                id: "run-detail-test".to_owned(),
                orchestrator_model: "composer-2.5".to_owned(),
                user_prompt: "track details".to_owned(),
                limits: dmuxai::graph::GraphLimits::default(),
                tasks: Vec::new(),
                nodes: vec![dmuxai::graph::GraphNode {
                    id: "step-1".to_owned(),
                    role: NodeRole::Implement,
                    job: "perform work".to_owned(),
                    runner: "agy".to_owned(),
                    model_id: "opencode-default".to_owned(),
                    skill: None,
                    requires_gate: false,
                    status: dmuxai::graph::GraphNodeStatus::Running,
                    attempt: 1,
                    task: None,
                    started_at_ms: None,
                    finished_at_ms: None,
                }],
                edges: vec![],
            },
            conversation_id: app.conversation_id.as_str().to_owned(),
            phase: GraphRunPhase::Active,
            waiting_gate_node: None,
            ..Default::default()
        }));
        app.busy_agents.insert(Agent::Agy);
        app.graph_agent_nodes
            .insert(Agent::Agy, "step-1".to_owned());

        // 1. Emit 25 lines of output, where line 15 is 350 chars long
        let mut output_text = String::new();
        for i in 1..=25 {
            if i == 15 {
                output_text.push_str(&"x".repeat(350));
            } else if i == 25 {
                output_text.push_str(&format!("{}extra", "x".repeat(299)));
                output_text.push('😀');
            } else if i == 20 {
                output_text.push_str("open http://127.0.0.1/?token=deadbeefcafe00");
            } else {
                output_text.push_str(&format!("log line {i}"));
            }
            output_text.push('\n');
        }
        app.apply_agent_event(Agent::Agy, AgentEvent::TextDelta(output_text));

        // 2. Emit write events:
        // - A tool event with workspace-relative path and diff stats
        app.apply_agent_event(
            Agent::Agy,
            AgentEvent::Activity(dmuxai::activity::ActivityItem::Tool {
                name: "edit".to_owned(),
                target: "src/app.rs (+12 -3)".to_owned(),
                status: dmuxai::activity::ToolStatus::Running,
                duration_ms: None,
                detail: String::new(),
            }),
        );
        // - A tool event with absolute path inside workspace
        let abs_path = app
            .workspace_root
            .join("src/main.rs")
            .to_string_lossy()
            .into_owned();
        app.apply_agent_event(
            Agent::Agy,
            AgentEvent::Activity(dmuxai::activity::ActivityItem::Tool {
                name: "write_to_file".to_owned(),
                target: abs_path,
                status: dmuxai::activity::ToolStatus::Running,
                duration_ms: None,
                detail: String::new(),
            }),
        );
        // - A tool event with path OUTSIDE workspace (must be ignored)
        app.apply_agent_event(
            Agent::Agy,
            AgentEvent::Activity(dmuxai::activity::ActivityItem::Tool {
                name: "edit".to_owned(),
                target: "/etc/outside.txt".to_owned(),
                status: dmuxai::activity::ToolStatus::Running,
                duration_ms: None,
                detail: String::new(),
            }),
        );
        // - More than 50 files to verify the 50 cap
        for i in 0..60 {
            app.apply_agent_event(
                Agent::Agy,
                AgentEvent::Activity(dmuxai::activity::ActivityItem::Tool {
                    name: "edit".to_owned(),
                    target: format!("src/file_{i}.rs"),
                    status: dmuxai::activity::ToolStatus::Running,
                    duration_ms: None,
                    detail: String::new(),
                }),
            );
        }

        app.publish_dashboard();

        let snapshot = hub.snapshot();
        let graph = snapshot.graph.expect("expected graph");
        let node = &graph.nodes[0];

        // Verify log_tail: last 20 lines (lines 6..=25)
        assert_eq!(node.detail.log_tail.len(), 20);
        assert_eq!(node.detail.log_tail[0], "log line 6");
        assert!(node.detail.log_tail[19].starts_with("xxx"));
        // Line 15 was 350 chars; in the 20-line window (index 15 - 6 = 9), it should be truncated to 300 chars + ellipsis
        assert_eq!(node.detail.log_tail[9].chars().count(), 301);
        assert!(node.detail.log_tail[9].ends_with('…'));
        assert_eq!(node.detail.log_tail[19].chars().count(), 301);
        assert!(node.detail.log_tail[19].ends_with('…'));
        assert!(
            !node
                .detail
                .log_tail
                .iter()
                .any(|line| line.contains("deadbeefcafe00")),
            "token query values must be redacted from log_tail"
        );

        // Verify changed_files:
        assert!(node.detail.changed_files.contains(&"src/app.rs".to_owned()));
        assert!(
            node.detail
                .changed_files
                .contains(&"src/main.rs".to_owned())
        );
        assert!(
            !node
                .detail
                .changed_files
                .iter()
                .any(|f| f.contains("outside"))
        );
        assert_eq!(node.detail.changed_files.len(), 50);
    }

    // FR-702: parallel runners attribute output to the correct node; retries reset detail.
    #[test]
    fn dashboard_node_detail_parallel_and_retry() {
        use dmuxai::graph::NodeAssignment;

        let (mut app, _sent) = test_app();
        let hub = dmuxai::web::DashboardHub::new(
            dmuxai::web::SnapshotSource::Tui,
            app.workspace_root.to_string_lossy().into_owned(),
        );
        app.attach_dashboard(hub.clone());

        app.graph_session = Some(GraphRunSession::new(GraphRun {
            plan: dmuxai::graph::GraphPlan {
                schema: "dmuxai.graph/v1".to_owned(),
                id: "parallel-detail".to_owned(),
                orchestrator_model: "composer-2.5".to_owned(),
                user_prompt: "parallel".to_owned(),
                limits: dmuxai::graph::GraphLimits {
                    max_parallel: 2,
                    max_retries: 2,
                    ..dmuxai::graph::GraphLimits::default()
                },
                tasks: Vec::new(),
                nodes: vec![
                    dmuxai::graph::GraphNode {
                        id: "node-a".to_owned(),
                        role: NodeRole::Implement,
                        job: "work a".to_owned(),
                        runner: "codex".to_owned(),
                        model_id: "m".to_owned(),
                        skill: None,
                        requires_gate: false,
                        status: dmuxai::graph::GraphNodeStatus::Running,
                        attempt: 1,
                        task: None,
                        started_at_ms: None,
                        finished_at_ms: None,
                    },
                    dmuxai::graph::GraphNode {
                        id: "node-b".to_owned(),
                        role: NodeRole::Review,
                        job: "work b".to_owned(),
                        runner: "cursor".to_owned(),
                        model_id: "m".to_owned(),
                        skill: None,
                        requires_gate: false,
                        status: dmuxai::graph::GraphNodeStatus::Running,
                        attempt: 1,
                        task: None,
                        started_at_ms: None,
                        finished_at_ms: None,
                    },
                ],
                edges: vec![],
            },
            conversation_id: app.conversation_id.as_str().to_owned(),
            phase: GraphRunPhase::Active,
            waiting_gate_node: None,
            ..Default::default()
        }));
        app.graph_agent_nodes
            .insert(Agent::Codex, "node-a".to_owned());
        app.graph_agent_nodes
            .insert(Agent::Cursor, "node-b".to_owned());
        app.busy_agents.insert(Agent::Codex);
        app.busy_agents.insert(Agent::Cursor);

        app.apply_agent_event(
            Agent::Codex,
            AgentEvent::TextDelta("codex-only\n".to_owned()),
        );
        app.apply_agent_event(
            Agent::Cursor,
            AgentEvent::TextDelta("cursor-only\n".to_owned()),
        );
        app.publish_dashboard();

        let graph = hub.snapshot().graph.expect("graph");
        let node_a = graph
            .nodes
            .iter()
            .find(|node| node.id == "node-a")
            .expect("node-a");
        let node_b = graph
            .nodes
            .iter()
            .find(|node| node.id == "node-b")
            .expect("node-b");
        assert!(
            node_a
                .detail
                .log_tail
                .iter()
                .any(|line| line.contains("codex-only"))
        );
        assert!(
            !node_a
                .detail
                .log_tail
                .iter()
                .any(|line| line.contains("cursor-only"))
        );
        assert!(
            node_b
                .detail
                .log_tail
                .iter()
                .any(|line| line.contains("cursor-only"))
        );
        assert!(
            !node_b
                .detail
                .log_tail
                .iter()
                .any(|line| line.contains("codex-only"))
        );

        app.graph_session = Some(GraphRunSession::new(GraphRun {
            plan: dmuxai::graph::GraphPlan {
                schema: "dmuxai.graph/v1".to_owned(),
                id: "retry-detail".to_owned(),
                orchestrator_model: "composer-2.5".to_owned(),
                user_prompt: "retry".to_owned(),
                limits: dmuxai::graph::GraphLimits::default(),
                tasks: Vec::new(),
                nodes: vec![dmuxai::graph::GraphNode {
                    id: "step-1".to_owned(),
                    role: NodeRole::Implement,
                    job: "retry work".to_owned(),
                    runner: "agy".to_owned(),
                    model_id: "m".to_owned(),
                    skill: None,
                    requires_gate: false,
                    status: dmuxai::graph::GraphNodeStatus::Running,
                    attempt: 2,
                    task: None,
                    started_at_ms: None,
                    finished_at_ms: None,
                }],
                edges: vec![],
            },
            conversation_id: app.conversation_id.as_str().to_owned(),
            phase: GraphRunPhase::Active,
            waiting_gate_node: None,
            ..Default::default()
        }));
        app.graph_agent_nodes
            .insert(Agent::Agy, "step-1".to_owned());
        app.apply_agent_event(
            Agent::Agy,
            AgentEvent::TextDelta("before-retry\n".to_owned()),
        );
        app.busy_agents.remove(&Agent::Agy);
        let assignment = NodeAssignment {
            node_id: "step-1".to_owned(),
            runner: "agy".to_owned(),
            model_id: "m".to_owned(),
            prompt: "retry work".to_owned(),
            role: NodeRole::Implement,
        };
        app.start_graph_node(assignment)
            .expect("start retry attempt");
        app.apply_agent_event(
            Agent::Agy,
            AgentEvent::TextDelta("after-retry\n".to_owned()),
        );
        app.publish_dashboard();

        let retry_graph = hub.snapshot().graph.expect("graph after retry");
        let retry_node = &retry_graph.nodes[0];
        assert!(
            retry_node
                .detail
                .log_tail
                .iter()
                .any(|line| line.contains("after-retry"))
        );
        assert!(
            !retry_node
                .detail
                .log_tail
                .iter()
                .any(|line| line.contains("before-retry"))
        );
    }

