    fn mark_task_done_in_plan(run: &mut GraphRun, task_id: &str) {
        for node in &mut run.plan.nodes {
            if node.task.as_deref() == Some(task_id) {
                node.status = GraphNodeStatus::Completed;
            }
        }
    }

